/**
 * How Three paper-mulberry leaves in a thin ring (`hosowa-ni-mitsu-kaji`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/hosowa-ni-mitsu-kaji";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"One upright leaf stands above a pair of angled leaves. Two curved arms rise beside a straight support inside a thin ring.","ja":"細輪の内側に、正面を向く梶の葉を上に一枚、傾けた葉を左右に一枚ずつ置きます。中央の直線の茎に沿って、左右の弧を立ち上げます。"};

export default construction;
export { construction, description };
